package com.xdownload.mobile;
import android.content.Context;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.*;import org.json.*;import com.yausername.youtubedl_android.*;
/** Explicit updates from official release metadata. A digest is required, never downloaded from arbitrary input. */
final class EngineUpdater {
 static final String API="https://api.github.com/repos/yt-dlp/yt-dlp/releases/latest";static final long LIMIT=24*1024*1024;
 static File binary(Context c){return new File(c.getNoBackupFilesDir(),"youtubedl-android/yt-dlp/yt-dlp");}
 static String version()throws Exception{YoutubeDLRequest req=new YoutubeDLRequest("https://example.org");req.addOption("--version");String value=YoutubeDL.getInstance().execute(req,null,null).getOut().trim();if(!value.matches("\\d{4}\\.\\d{2}\\.\\d{2}(?:[.a-zA-Z0-9_-]*)"))throw new IOException("Engine version check failed");return value;}
 static byte[] read(String url,int limit)throws Exception{HttpURLConnection con=HttpEngine.connect(url,false,"GET",0,"");try{if(con.getResponseCode()!=200)throw new IOException("Update HTTP "+con.getResponseCode());try(InputStream in=con.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Release metadata too large");out.write(b,0,n);}return out.toByteArray();}}finally{con.disconnect();}}
 static String digest(JSONObject asset)throws IOException{String expected=asset.optString("digest");if(!expected.matches("sha256:[a-fA-F0-9]{64}"))throw new IOException("Release has no SHA-256 digest; update refused");return expected.substring(7).toLowerCase(Locale.ROOT);}
 static void atomic(File source,File dest)throws IOException{Files.move(source.toPath(),dest.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
 static String update(Context c)throws Exception{if(!MediaEngine.ENGINE.writeLock().tryLock())throw new IOException("Finish current media analysis and downloads first");File temp=null;try{MediaEngine.init(c);String old=version();JSONObject meta=new JSONObject(new String(read(API,2*1024*1024),java.nio.charset.StandardCharsets.UTF_8));String tag=meta.optString("tag_name");if(!tag.matches("\\d{4}\\.\\d{2}\\.\\d{2}"))throw new IOException("Unexpected release version");if(tag.equals(old))return "Already current: "+old;if(old.matches("\\d{4}\\.\\d{2}\\.\\d{2}")&&tag.compareTo(old)<0)throw new IOException("Downgrade refused");JSONArray assets=meta.getJSONArray("assets");JSONObject chosen=null;for(int i=0;i<assets.length();i++){JSONObject a=assets.optJSONObject(i);if(a!=null&&"yt-dlp".equals(a.optString("name"))){chosen=a;break;}}if(chosen==null)throw new IOException("Official executable not found");String sha=digest(chosen);String url=chosen.optString("browser_download_url");if(!url.equals("https://github.com/yt-dlp/yt-dlp/releases/download/"+tag+"/yt-dlp"))throw new IOException("Unexpected asset origin");long expected=chosen.optLong("size",-1);if(expected<=0||expected>LIMIT)throw new IOException("Unexpected engine size");File live=binary(c),backup=new File(live.getPath()+".previous"),copy=new File(live.getPath()+".backup.tmp");temp=File.createTempFile("engine-",".tmp",live.getParentFile());HttpURLConnection con=HttpEngine.connect(url,false,"GET",0,"");try{if(con.getResponseCode()!=200)throw new IOException("Asset HTTP "+con.getResponseCode());try(InputStream in=con.getInputStream();FileOutputStream out=new FileOutputStream(temp)){byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>expected)throw new IOException("Unexpected asset length");out.write(b,0,n);}out.getFD().sync();if(total!=expected)throw new IOException("Incomplete asset");}}finally{con.disconnect();}if(!sha.equals(HttpEngine.sha256(temp)))throw new IOException("Digest mismatch; update refused");try{Files.copy(live.toPath(),copy.toPath(),StandardCopyOption.REPLACE_EXISTING);atomic(copy,backup);atomic(temp,live);temp=null;try{String result=version();if(!tag.equals(result))throw new IOException("Version mismatch");return "Updated: "+old+" → "+result;}catch(Exception ex){atomic(backup,live);throw new IOException("Update failed self-test; previous engine restored",ex);}}finally{copy.delete();}}finally{if(temp!=null)temp.delete();MediaEngine.ENGINE.writeLock().unlock();}}
 static String rollback(Context c)throws Exception{if(!MediaEngine.ENGINE.writeLock().tryLock())throw new IOException("Finish current media operations first");try{MediaEngine.init(c);File live=binary(c),previous=new File(live.getPath()+".previous"),save=new File(live.getPath()+".rollback.tmp");if(!previous.isFile())throw new IOException("No previous engine stored");Files.copy(live.toPath(),save.toPath(),StandardCopyOption.REPLACE_EXISTING);try{atomic(previous,live);try{String v=version();save.delete();return "Restored "+v;}catch(Exception e){atomic(save,live);throw e;}}finally{save.delete();}}finally{MediaEngine.ENGINE.writeLock().unlock();}}
}